function s(v) { return String(v == null ? '' : v).trim(); }
function isIAN(x) { return s(x).toLowerCase().indexOf('ian group') === 0; }
const WANT = ['Luxova', 'Nexcore', 'EosNox'];

const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

const ianRows = rows.filter(function (r) { return isIAN(r.investor); });
const names = {};
for (const r of ianRows) { names[s(r.investor)] = (names[s(r.investor)] || 0) + 1; }

const found = [];
for (const w of WANT) {
  const hits = ianRows.filter(function (r) { return s(r.startup).toLowerCase() === w.toLowerCase(); });
  if (hits.length === 0) { found.push({ startup: w, status: 'NO ROW - would need creating' }); continue; }
  for (const h of hits) {
    found.push({ startup: w, status: 'found', deal_id: s(h.deal_id), investor: s(h.investor),
      owner: s(h.owner), deal_shared: s(h.deal_shared), date_shared: s(h.date_shared),
      next_action: s(h.next_action), next_due: s(h.next_due), pause: s(h.pause),
      investor_response: s(h.investor_response), meeting_scheduled: s(h.meeting_scheduled),
      meeting_date: s(h.meeting_date), deal_status: s(h.deal_status) });
  }
}

return [{ json: {
  total_ian_rows: ianRows.length,
  ian_names_present: names,
  targets: found
}}];
